(7274155, 1132239, 170281, '<td valign="top">Unless this was a tomato soup bath to rid one of a skunk smell, this is very disturbing.</td>', 'Unless this was a tomato soup bath to rid one of a skunk smell, this is very disturbing.', '2014-10-16 11:37:27.000000', NULL, 1),
(7274158, 1132392, 170281, '<td valign="top">Very nicely done.  The framing, clarity and color are excellent.</td>', 'Very nicely done.  The framing, clarity and color are excellent.', '2014-10-16 11:44:38.000000', NULL, 1),
(7274161, 1132307, 170281, '<td valign="top">Great concept layout and photo.</td>', 'Great concept layout and photo.', '2014-10-16 11:45:52.000000', NULL, 1),
(7274167, 1132275, 170281, '<td valign="top">Great contrast and simplicity.</td>', 'Great contrast and simplicity.', '2014-10-16 11:52:08.000000', NULL, 1),
(7274168, 1132193, 170281, '<td valign="top">Funny!</td>', 'Funny!', '2014-10-16 11:58:21.000000', NULL, 1),
(7274172, 1132250, 170281, '<td valign="top">Nice subject matter.  I wonder what it would have looked like from the sun exposed side.</td>', 'Nice subject matter.  I wonder what it would have looked like from the sun exposed side.', '2014-10-16 12:15:09.000000', NULL, 1),
(7274177, 1132242, 13077, '<td valign="top">Nicely arranged and good filling of the frame.</td>', 'Nicely arranged and good filling of the frame.', '2014-10-16 12:37:21.000000', NULL, 1),
(7274179, 1132555, 13077, '<td valign="top">It seems underexposed to me; the soft light works well and the textures of the background and worn surface of the wheelbarrow look good, but it''s very dark.</td>', 'It seems underexposed to me; the soft light works well and the textures of the background and worn surface of the wheelbarrow look good, but it''s very dark.', '2014-10-16 12:39:07.000000', NULL, 1),
(7274180, 1132459, 13077, '<td valign="top">The lens flare is unattractive to me.</td>', 'The lens flare is unattractive to me.', '2014-10-16 12:39:29.000000', NULL, 1),
(7274181, 1132229, 13077, '<td valign="top">Good concept, well done. Pretty polished for minimal editing, nicely done setup.</td>', 'Good concept, well done. Pretty polished for minimal editing, nicely done setup.', '2014-10-16 12:40:16.000000', NULL, 1),
(7274186, 1132527, 13077, '<td valign="top">Good light and composition here.<br/>I''d prefer fall.</td>', 'Good light and composition here.I''d prefer fall.', '2014-10-16 12:45:06.000000', NULL, 1),
(7274187, 1132277, 13077, '<td valign="top">I like it - bold, simple, colorful.</td>', 'I like it - bold, simple, colorful.', '2014-10-16 12:45:23.000000', NULL, 1),
(7274188, 1132559, 13077, '<td valign="top">I''m not crazy about this - the softness, the composition or the fact that I don''t see anything red in it.</td>', 'I''m not crazy about this - the softness, the composition or the fact that I don''t see anything red in it.', '2014-10-16 12:48:33.000000', NULL, 1),
(7274189, 1132467, 13077, '<td valign="top">Nicely composed, but a different light source might have made the overall look of it a bit cleaner - red roses are tough to shoot though.</td>', 'Nicely composed, but a different light source might have made the overall look of it a bit cleaner - red roses are tough to shoot though.', '2014-10-16 12:51:16.000000', NULL, 1),
(7274192, 1132418, 13077, '<td valign="top">I like it - the out-of-focus parts of the tree are pleasantly colored and almost abstract, and the dew drops on the berries look great.</td>', 'I like it - the out-of-focus parts of the tree are pleasantly colored and almost abstract, and the dew drops on the berries look great.', '2014-10-16 13:04:29.000000', NULL, 1),
(7274193, 1132362, 13077, '<td valign="top">Meets the challenge, and well exposed and well placed focus.</td>', 'Meets the challenge, and well exposed and well placed focus.', '2014-10-16 13:05:20.000000', NULL, 1),
(7274194, 1132193, 13077, '<td valign="top">Cute concept, well done.</td>', 'Cute concept, well done.', '2014-10-16 13:05:40.000000', NULL, 1),
(7274214, 1132165, 153814, '<td valign="top">This is one of those shots that seem so simple yet so perfect.<br/>I gave two 10''s in this challenge and this is one of them.<br/></td>', 'This is one of those shots that seem so simple yet so perfect.I gave two 10''s in this challenge and this is one of them.', '2014-10-16 14:30:37.000000', NULL, 1),
